void ScriptSession::aiCancelBoarding(unsigned owner,std::uint32_t passenger,std::uint32_t carrier){
    if(!alive(passenger,NativeKind::Unit))return;auto u=units_.at(passenger);if(u->owner!=owner || u->transport || u->combat.board!=carrier)return;auto revision=u->combat.revision;if(!stopUnit(passenger) && alive(passenger,NativeKind::Unit) && u->owner==owner && !u->transport && u->combat.board==carrier && u->combat.revision==revision){u->combat.board=0;u->route.clear();u->waypoint=0;u->currentOrder=0;++u->combat.revision;}
}
void ScriptSession::aiCancelPickupSailing(unsigned owner,std::uint32_t carrier,std::uint64_t revision){
    if(!alive(carrier,NativeKind::Unit))return;auto ship=units_.at(carrier);if(ship->owner!=owner || pathMovement(ship->movementType)!=PathMovement::Water || ship->currentOrder!=851986 || ship->combat.revision!=revision)return;if(!stopUnit(carrier) && alive(carrier,NativeKind::Unit) && ship->owner==owner && ship->combat.revision==revision && ship->currentOrder==851986){ship->route.clear();ship->waypoint=0;ship->currentOrder=0;++ship->combat.revision;}
}
